const deal = $('Deal Proposal Stage Webhook').first().json;
const config = $('Get Config').first().json;
const props = deal.properties || deal;

return [{
  json: {
    clientName: props.dealname || props.name || '',
    company: props.company || props.dealname || '',
    industry: props.industry || '',
    painPoints: props.deal_pain_points || props.painPoints || props.pain_point_summary || '',
    dealValue: props.amount || 0,
    tier: props.tier || 'starter',
    dealId: deal.id || deal.dealId || '',
    contactEmail: props.contact_email || props.email || '',
    contactFirstName: props.contact_firstname || props.firstName || '',
    driveFolderId: props.client_drive_folder_id || '',
    config
  }
}];

const d = $('Extract Deal Data').first().json;
const tierInfo = d.config.tiers[d.tier] || d.config.tiers.starter;
const painPointsBlock = (d.painPoints || '').trim() ? d.painPoints.trim() : '(None provided)';

return [{
  json: {
    systemPrompt: 'You are writing a formal consulting proposal for IntraWeb Technologies LLC. We are the implementation layer for AI-enabled operations; we build, we do not just advise. Tone: direct, confident, professional. Use specific outcomes and numbers. Return ONLY the main proposal body as clean semantic HTML: no DOCTYPE, no html/head/body tags, no markdown, no backticks. Use headings (h2, h3), paragraphs, and lists. The content will be wrapped in a branded PDF template.

MANDATORY — Pain points from the payload:
1. The Problem section MUST quote or closely paraphrase the EXACT pain points provided in the user message. Do not substitute generic challenges. Use the customer's own words or near-verbatim. List each distinct pain point they provided.
2. What We'll Build MUST be structured as one bullet or paragraph per pain point. For each pain point from The Problem, write exactly how we address it: use the format "You said [their pain] — we address this by [specific automation/solution]." Do not write a generic list of capabilities. Every item in What We'll Build must explicitly reference a pain point stated above.

Investment: Use ONLY the package and numbers provided in the user message. Do not mention other packages.',
    userPrompt: `Write a complete, professional consulting proposal.

Client: ${d.clientName}
Company: ${d.company}
Industry: ${d.industry}
Deal Value: $${d.dealValue}

CUSTOMER PAIN POINTS FROM PAYLOAD — You MUST use these in The Problem (in their words) and map each one to a specific solution in What We'll Build:
"""
${painPointsBlock}
"""

PACKAGE (use only this in Investment): ${tierInfo.name} — $${tierInfo.monthlyPrice}/month + $${tierInfo.setupFee} one-time setup. Investment section must show exactly $${tierInfo.monthlyPrice}/mo and $${tierInfo.setupFee} setup.

Sections (in order):
1. Executive Summary
2. The Problem — state each pain point from the block above in the customer's words; do not generalize.
3. What We'll Build — for EACH pain point above, one bullet/paragraph: "You said [X] — we address this by [Y]."
4. Timeline (8-week implementation)
5. Investment (${tierInfo.name} figures only)
6. Why IntraWeb
7. Next Steps

Return only HTML body content.`,
    maxTokens: 4000
  }
}];

const raw = $('Call Claude API').first().json;
const text = (raw.content && raw.content[0] && raw.content[0].text) ? raw.content[0].text : '';
const d = $('Extract Deal Data').first().json;
return [{ json: { data: { text }, html: text, fileName: `IntraWeb — ${d.clientName} — Proposal.pdf` } }];

const claudeResult = $('Parse Claude Response').first().json;
const d = $('Extract Deal Data').first().json;
const config = d.config || {};
const branding = config.branding || {};
const owner = config.owner || {};
const companyName = owner.companyName || 'IntraWeb Technologies LLC';
const ownerEmail = owner.email || '';
const ownerPhone = owner.phone || '';
const bodyContent = (claudeResult.data ? claudeResult.data.text : claudeResult.html || '').trim();
const clientName = d.clientName || 'Client';
const proposalDate = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
const DEFAULT_LOGO_BASE64 = '';
const logoSrc = branding.logoUrl || (DEFAULT_LOGO_BASE64 ? 'data:image/webp;base64,' + DEFAULT_LOGO_BASE64 : '');

const html = `<!DOCTYPE html>
<html lang=\"en\">
<head>
  <meta charset=\"UTF-8\">
  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">
  <title>Proposal for ${clientName} — ${companyName}</title>
  <link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">
  <style>
    @page { size: letter; margin: 0.85in 0.75in; }
    * { box-sizing: border-box; }
    body { font-family: 'DM Sans', sans-serif; color: #1a1f2e; margin: 0; padding: 0 0 0 0; line-height: 1.55; font-size: 14px; padding-top: 44px; padding-bottom: 28px; min-height: 100vh; }
    .page-header { position: fixed; top: 0; left: 0; right: 0; height: 64px; padding: 12px 0.75in 0; background: #fff; border-bottom: 2px solid #E87B2B; display: flex; align-items: center; gap: 14px; z-index: 10; }
    .page-header img { height: 40px; width: auto; display: block; }
    .page-header .company-name { font-size: 16px; font-weight: 700; color: #6B4E9B; margin: 0; }
    .page-header .proposal-title { font-size: 12px; color: #5a6578; margin: 2px 0 0 0; }
    .page-footer { position: fixed; bottom: 0; left: 0; right: 0; min-height: 56px; padding: 6px 0.75in 8px; background: #fff; border-top: 1px solid #e5e7eb; font-size: 11px; color: #6b7280; display: flex; flex-direction: column; justify-content: flex-end; align-items: stretch; z-index: 10; gap: 4px; }
    .proposal-body { max-width: 100%; padding: 0; }
    .proposal-body h2 { color: #6B4E9B; font-size: 18px; margin: 22px 0 10px 0; page-break-after: avoid; }
    .proposal-body h3 { color: #1a1f2e; font-size: 15px; margin: 14px 0 6px 0; page-break-after: avoid; }
    .proposal-body p { margin: 0 0 10px 0; }
    .proposal-body ul, .proposal-body ol { margin: 0 0 10px 0; padding-left: 20px; page-break-inside: avoid; }
    .proposal-body li { margin-bottom: 4px; }
    .proposal-body section, .proposal-body .section { page-break-inside: avoid; }
    .highlight { background: #f5f2f8; border-left: 4px solid #E87B2B; padding: 10px 14px; margin: 12px 0; border-radius: 0 4px 4px 0; page-break-inside: avoid; }
    .cta { background: linear-gradient(135deg, #6B4E9B 0%, #5a3d84 100%); color: #fff; padding: 16px 20px; margin-top: 20px; border-radius: 6px; text-align: center; page-break-inside: avoid; }
  </style>
</head>
<body>
  <header class=\"page-header\">
    ${logoSrc ? `<img src=\"${logoSrc}\" alt=\"IntraWeb\" />` : '<span style=\"font-size:24px;font-weight:700;color:#6B4E9B\">I</span><span style=\"font-size:24px;font-weight:700;color:#E87B2B\">W</span>'}
    <p class=\"proposal-title\">Proposal for ${clientName}</p>
  </header>
  <main class=\"proposal-body\">
    ${bodyContent}
  </main>
  <footer class=\"page-footer\">
    <div style=\"display:flex;justify-content:space-between;\"><span>${companyName}</span><span>Confidential — ${proposalDate}</span></div>
    <div style=\"display:flex;justify-content:space-between;flex-wrap:wrap;gap:4px;\"><span>Contact: ${ownerEmail}${ownerPhone ? ' | ' + ownerPhone : ''}</span><span>To approve: set Status to Approved in the Proposals queue, or reply to the proposal email.</span></div>
  </footer>
</body>
</html>`;

return [{ json: { html, fileName: `IntraWeb — ${d.clientName} — Proposal.pdf` } }];

const item = $input.first();
const fileName = $('Prep PDF Input').first().json.fileName || 'document.pdf';
return [{ json: { fileName }, binary: item.binary ? { ...item.binary } : {} }];

const d = $('Extract Deal Data').first().json;
const uploadOut = $('Upload to Drive').first();
const fileId = uploadOut?.json?.id ?? uploadOut?.json?.data?.id ?? '';
const driveLink = fileId ? 'https://drive.google.com/file/d/' + fileId : '';

return [{
  json: {
    message: driveLink ? `Proposal ready for ${d.clientName} — set Status to Approved to send: ${driveLink}` : `Proposal ready for ${d.clientName} — set Status to Approved to send. (Drive link unavailable.)`,
    priority: 'info'
  }
}];

const d = $('Extract Deal Data').first().json;
const uploadOut = $('Upload to Drive').first();
const fileId = uploadOut?.json?.id ?? uploadOut?.json?.data?.id ?? '';
const driveLink = fileId ? 'https://drive.google.com/file/d/' + fileId : '';

return [{
  json: {
    to: d.contactEmail,
    subject: `Your IntraWeb proposal is ready — ${d.clientName}`,
    html: `<p>Hi ${d.contactFirstName || 'there'},</p><p>Your proposal is attached. I've outlined exactly what we'll build, the timeline, and the investment.</p>${driveLink ? `<p>You can also <a href="${driveLink}">view it in Google Drive here</a>.</p>` : ''}<p>Take a look and let me know if you have any questions. When you're ready to move forward, reply to this email and I'll send the contract for e-signature.</p><p>— John<br/>${d.config?.owner?.companyName || 'IntraWeb'}</p>`,
    workflowName: 'SYS 05: Proposal & Contract Delivery'
  }
}];

return [{
  json: {
    workflowName: 'SYS 05: Proposal & Contract Delivery',
    contactName: $('Extract Deal Data').first().json.clientName,
    phone: '',
    eventType: 'proposal_sent',
    status: 'success',
    notes: `Deal value: $${$('Extract Deal Data').first().json.dealValue}`
  }
}];
